function clamp01(value) {
  return Math.min(1, Math.max(0, value));
}

function advanceContinualValue(current, target) {
  const value = Number.isFinite(current) ? clamp01(current) : 0;
  const destination = Number.isFinite(target) ? clamp01(target) : Math.random();
  const difference = destination - value;
  const step = randomizationSpeed * Math.max(0, Math.min(0.1, lastFrameDeltaSeconds));

  if (Math.abs(difference) <= step) {
    return { value, target: Math.random(), changed: false };
  }

  return {
    value: clamp01(value + Math.sign(difference) * step),
    target: destination,
    changed: true
  };
}

function createSeededRandom(seed) {
  return function() {
    seed = (seed * 9301 + 49297) % 233280;
    return seed / 233280;
  };
}
