function resize() {
  glitchCanvas.width = window.innerWidth;
  glitchCanvas.height = window.innerHeight;
}
resize();
window.addEventListener('resize', resize);

function createTimedEffect(fn, duration = 3000 + Math.random() * 3000) {
  const startTime = performance.now();
  let timedEffect; 
  timedEffect = function() {
    const elapsed = performance.now() - startTime;
    if (elapsed > duration) {
      const index = activeEffects.indexOf(timedEffect);
      if (index > -1) activeEffects.splice(index, 1);
      return;
    }
    fn();
  };
  return timedEffect;
}

function createPersistentEffect(fn) {
  return function() {
    fn();
  };
}

function glitchASCIIArtOverlayFactory(getStrength, isPersistent = false) {
 const render=()=>{const strength=getStrength();if(strength<=.001)return;const w=glitchCanvas.width,h=glitchCanvas.height,spacing=Math.max(19,36-strength*14);gctx.save();gctx.font=`bold ${Math.round(spacing*.7)}px monospace`;gctx.textBaseline='middle';gctx.fillStyle=`rgba(170,255,210,${.55*strength})`;gctx.globalCompositeOperation='screen';
  for(let y=spacing*.5;y<h;y+=spacing){for(let x=spacing*.5;x<w;x+=spacing){if(Math.random()<.16+strength*.32)gctx.fillText(SignalGlyphs.pick(),x,y);}}
  gctx.restore();};return isPersistent?render:createTimedEffect(render);
}

