// --- Glitch Overlay Logic (from midi+mp3.html, adapted for constant effect) ---
let glitchOverlayActive = false;
function startGlitchOverlay() {
  glitchOverlayActive = true;
  if (!window.isGlitchOverlayLoopRunning) {
    updateGlitchOverlay();
  }
}

function stopGlitchOverlay() {
  glitchOverlayActive = false;
  let overlay = document.getElementById('color-shift-overlay');
  if (overlay) {
    overlay.style.opacity = '0';
  }
}

function updateGlitchOverlay() {
  window.isGlitchOverlayLoopRunning = true;
  if (glitchOverlayActive) {
    const time = Date.now();
    // --- Intensity-driven Opacity Pulse ---
    const pulseSpeed = 12000;
    const pulse = (Math.sin(time / pulseSpeed * Math.PI * 2) + 1) / 2;
    const blendIntensity = 0.7 * pulse; // Use a constant intensity for visual effect

    // --- Slow, Random Color Gradient Cycle ---
    const gradientChangeSpeed = 20000;
    if (!window.lastGradientUpdateTime || (time - window.lastGradientUpdateTime > gradientChangeSpeed)) {
      window.lastGradientUpdateTime = time;
      const randomAngle = Math.random() * 360;
      const color1 = `hsl(${Math.random() * 360}, 100%, 60%)`;
      const color2 = `hsl(${Math.random() * 360}, 100%, 60%)`;
      const color3 = `hsl(${Math.random() * 360}, 100%, 60%)`;
      window.currentGradient = `linear-gradient(${randomAngle}deg, ${color1}, ${color2}, ${color3})`;
    }

    // Get or create overlay element
    let overlay = document.getElementById('color-shift-overlay');
    if (!overlay) {
      overlay = document.createElement('div');
      overlay.id = 'color-shift-overlay';
      Object.assign(overlay.style, {
        position: 'absolute',
        top: '0',
        left: '0',
        width: '100%',
        height: '100%',
        pointerEvents: 'none',
        mixBlendMode: 'color-dodge',
        zIndex: '3',
        opacity: '0',
        transition: 'opacity 0.8s ease'
      });
      document.getElementById('effects-wrapper').appendChild(overlay);
    }

    // Apply the dynamic styles
    overlay.style.opacity = blendIntensity;
    if (window.currentGradient) {
      overlay.style.background = window.currentGradient;
    }
    document.body.style.filter = 'none';
  }
  if (glitchOverlayActive) requestAnimationFrame(updateGlitchOverlay);
  else window.isGlitchOverlayLoopRunning = false;
}


let isAutoGlitching = false;
function persistentAutoGlitchLoop() {
  activeEffects = []; // Always clear effects for a clean state
  if (isAutoGlitching) {
    timedEffectsDefs.forEach(def => {
      const getStrength = () => effectAlphas[def.name] * masterOpacity;
      const persistentEffectFn = def.factory(getStrength, true);
      activeEffects.push(persistentEffectFn);
    });
  }
}

autoGlitchBtn.addEventListener('click', () => {
  isAutoGlitching = !isAutoGlitching;
  autoGlitchBtn.textContent = isAutoGlitching ? 'Auto Glitch: ON' : 'Auto Glitch: OFF';
  persistentAutoGlitchLoop();
});

function mainRenderLoop() {
  if (!document.body.classList.contains('playing')) { isLooping=false; lastFrameTime=performance.now(); gctx.clearRect(0,0,glitchCanvas.width,glitchCanvas.height); return; }
  isLooping = true;
  const now = performance.now();
  // Cap canvas work at 30fps, rather than burning CPU on 120/144Hz displays.
  if (now - lastFrameTime < 1000 / 30) { requestAnimationFrame(mainRenderLoop); return; }
  const deltaTime = now - lastFrameTime;
  lastFrameTime = now;
  lastFrameDeltaSeconds = deltaTime * 0.001;
  const dataBombStrength = effectAlphas['Data Bomb'] * masterOpacity;
  const maxSpeed = 2.0;
  const minSpeed = 0.1;
  timeScale = maxSpeed - (dataBombStrength * (maxSpeed - minSpeed));
  customTime += deltaTime * timeScale;
  masterBeat = (Math.sin(customTime / 200) + 1) / 2;
  gctx.clearRect(0, 0, glitchCanvas.width, glitchCanvas.height);
  activeEffects.slice().forEach(fn => {
    try { gctx.save(); fn(); }
    catch (error) { console.warn('Effect stopped after an error:', error); activeEffects = activeEffects.filter(active => active !== fn); }
    finally { gctx.restore(); }
  });

  if (isContinuallyRandomizing) {
    if (!sliderLocks.global) {
      const next = advanceContinualValue(masterOpacity, randomTargetAlphas.global);
      masterOpacity = next.value;
      randomTargetAlphas.global = next.target;
      globalSlider.value = masterOpacity.toFixed(3);
    }

    Object.keys(effectAlphas).forEach(key => {
      if (!sliderLocks[key]) {
      const next = advanceContinualValue(effectAlphas[key], randomTargetAlphas[key]);
      effectAlphas[key] = next.value;
      randomTargetAlphas[key] = next.target;
      if (sliderElements[key]) sliderElements[key].value = effectAlphas[key].toFixed(3);
      }
    });
  }

  if (isAiWarpActive) {
    // --- Warping animation ("twists" and "crunches")
    const warpAmount = 50;
    const largeFreq = 0.002 + Math.sin(customTime / 8000) * 0.0015;
    const smallFreq = 0.03 + Math.cos(customTime / 3000) * 0.02;
    if (feTurbulenceLarge) feTurbulenceLarge.setAttribute('baseFrequency', largeFreq);
    if (feTurbulenceSmall) feTurbulenceSmall.setAttribute('baseFrequency', smallFreq);
    if (feDisplacement) feDisplacement.setAttribute('scale', warpAmount * masterBeat);
    
    // --- Hue/Color Cycle for AI Warp ---
    const hueStrength = (effectAlphas['Hue/Color Cycle'] ?? 0) * masterOpacity;
    if (hueStrength > 0.01 && feColorMatrix) {
        const angle = hueStrength * 360;
        feColorMatrix.setAttribute('values', angle);
    } else if (feColorMatrix) {
        feColorMatrix.setAttribute('values', '0');
    }
  }
  
  applyMasterFilters();
  requestAnimationFrame(mainRenderLoop);
}

randomSeedSlider.addEventListener('input', () => {
    const seed = parseFloat(randomSeedSlider.value);
    const seededRandom = createSeededRandom(seed);

    // Set the animation timeline to a random point ("time slice")
    customTime = seededRandom() * 86400000; // Random time within a 24-hour equivalent in ms

    // Set global opacity (not lockable)
    if (!sliderLocks.global) {
        const randomGlobalOpacity = seededRandom();
        masterOpacity = randomGlobalOpacity;
        globalSlider.value = randomGlobalOpacity;
    }

    // Set effect alphas for all sliders based on the seed ("script point")
    Object.keys(effectAlphas).forEach(effectName => {
        if (!sliderLocks[effectName]) { // Only randomize if not locked
            const randomValue = seededRandom();
            effectAlphas[effectName] = randomValue;
            if (sliderElements[effectName]) {
                sliderElements[effectName].value = randomValue;
            }
        }
    });

    // The "script burst" logic that was here has been removed as requested.
});

