let isUIHidden = false; // Initial state: UI is visible
let tabHideTimer = null; // Timer to auto-hide the tab on mobile

toggleUiBtn.addEventListener('click', () => {
  isUIHidden = !isUIHidden;
  if (isUIHidden) {
    document.body.classList.add('ui-hidden');
    toggleUiBtn.textContent = 'SHOW CONTROL U.I.';
  } else {
    document.body.classList.remove('ui-hidden');
    toggleUiBtn.textContent = 'HIDE CONTROL U.I.';
  }
  // On mobile, restart the hide timer after the button is clicked
  if ('ontouchstart' in window) {
    clearTimeout(tabHideTimer);
    tabHideTimer = setTimeout(hideTab, 3000); // Hide after 3 seconds
  }
});

function hideTab() {
    uiToggleTab.style.right = '-145px'; // Use the same value as the initial CSS
    uiToggleTab.style.opacity = '0.4';
}

// For touch devices, ensure the tab expands on tap
uiToggleTab.addEventListener('touchstart', () => {
  // If a timer is already running, clear it
  clearTimeout(tabHideTimer);
  uiToggleTab.style.right = '0';
  uiToggleTab.style.opacity = '1';
});

uiToggleTab.addEventListener('touchend', () => {
  // Start a timer to hide the tab after a few seconds
  tabHideTimer = setTimeout(hideTab, 3000); // 3 seconds
});



