[autoGlitchBtn,continualRandomizeBtn,aiWarpBtn].forEach(b=>new MutationObserver(()=>b.classList.toggle('active',b.textContent.includes('ON'))).observe(b,{childList:true,characterData:true,subtree:true}));
document.querySelectorAll('#sliderContainer .slider-group').forEach(group=>{const label=group.querySelector('label'),range=group.querySelector('input');if(label&&range&&!range.id){range.setAttribute('aria-label',label.textContent.replace(':',''));}});

/* MACHINE presets are immutable embedded snapshots, not randomly generated at runtime. */
const machinePresets=Object.freeze(MACHINE_PRESET_DATA.map(p=>Object.freeze({...p,settings:Object.freeze({...p.settings,effects:Object.freeze({...p.settings.effects}),sliderLocks:Object.freeze({})})})));
const presetKey='glitchCanvasPresets_v2';
const mSelect=document.getElementById('machine-select'),mSearch=document.getElementById('machine-search'),uSelect=document.getElementById('user-presets'),uName=document.getElementById('user-preset-name'),presetStatus=document.getElementById('preset-status');
let userPresets=[];let selectedMachine='';let storageAvailable=true;
function sayPreset(message,isError=false){presetStatus.textContent=message;presetStatus.classList.toggle('error',isError);}
function clone(v){return JSON.parse(JSON.stringify(v));}
function cleanNumber(value,fallback=0){const n=Number(value);return Number.isFinite(n)?Math.max(0,Math.min(1,n)):fallback;}
function validPreset(p){return !!(p && typeof p==='object' && typeof p.name==='string' && p.name.trim() && p.name.length<=80 && p.settings && typeof p.settings==='object' && p.settings.effects && typeof p.settings.effects==='object' && !Array.isArray(p.settings.effects));}
function snapshot(){return {version:3,masterOpacity:cleanNumber(masterOpacity,1),effects:{...effectAlphas},isAutoGlitching,isContinuallyRandomizing,isAiWarpActive,sliderLocks:{...sliderLocks},glyphBank:SignalGlyphs.current,randomSeed:cleanNumber(randomSeedSlider.value),customTime:Number.isFinite(customTime)?customTime:0};}
function lockUI(){Object.keys(sliderLocks).forEach(name=>{const button=name==='global'?globalLockButton:sliderElements[name]?.parentElement?.querySelector('.lock-button');if(button){button.classList.toggle('locked',!!sliderLocks[name]);button.textContent=sliderLocks[name]?'[LOCKED!]':'<LOCK!>';}});}
function applySnapshot(s){
 if(!s || !s.effects || typeof s.effects!=='object')throw new Error('Invalid preset settings');
 window.applyingPreset=true;
 try{
  isContinuallyRandomizing=false;
  Object.keys(effectAlphas).forEach(name=>{effectAlphas[name]=cleanNumber(s.effects[name]);sliderElements[name].value=effectAlphas[name];});
  masterOpacity=cleanNumber(s.masterOpacity,1);globalSlider.value=masterOpacity;
  Object.keys(sliderLocks).forEach(name=>{sliderLocks[name]=!!(s.sliderLocks && s.sliderLocks[name]);});lockUI();
  randomSeedSlider.value=cleanNumber(s.randomSeed);if(Number.isFinite(s.customTime)) customTime=s.customTime;
  SignalGlyphs.set(s.glyphBank||'All scripts');updateGlyphCount();
  const scan=sliderElements['Scanlines'];if(scan)scan.dispatchEvent(new Event('input'));
  isAutoGlitching=!!s.isAutoGlitching;autoGlitchBtn.textContent=isAutoGlitching?'Auto Glitch: ON':'Auto Glitch: OFF';persistentAutoGlitchLoop();
  isContinuallyRandomizing=!!s.isContinuallyRandomizing;continualRandomizeBtn.textContent=isContinuallyRandomizing?'Continual Randomization: ON':'Continual Randomization: OFF';if(isContinuallyRandomizing)generateNewRandomTargets();
  isAiWarpActive=!!s.isAiWarpActive;aiWarpBtn.textContent=`AI Video Warp: ${isAiWarpActive?'ON':'OFF'}`;
  if(isAiWarpActive){sourceVideo.style.filter='brightness(0.9) contrast(1.1) url(#ai-warp-filter)';startGlitchOverlay();}else{sourceVideo.style.filter='brightness(0.9) contrast(1.1)';stopGlitchOverlay();}
  if(!isLooping)mainRenderLoop();
  document.querySelectorAll('[data-look]').forEach(b=>b.classList.remove('selected'));
 }finally{window.applyingPreset=false;}
}
function refreshUser(selected=''){
 uSelect.replaceChildren();const place=document.createElement('option');place.value='';place.textContent='Choose a saved preset';uSelect.appendChild(place);
 userPresets.forEach((p,i)=>{const opt=document.createElement('option');opt.value=String(i);opt.textContent=p.name;uSelect.appendChild(opt)});uSelect.value=selected;
}
function readUser(){try{const raw=localStorage.getItem(presetKey);const data=raw?JSON.parse(raw):[];if(!Array.isArray(data))throw Error('Not an array');userPresets=data.filter(validPreset);if(data.length!==userPresets.length)sayPreset('Some stored presets were invalid and are not displayed.',true);}catch(e){storageAvailable=false;userPresets=[];sayPreset('Browser storage could not be read. Import a backup or enable storage.',true);}refreshUser();}
function storeUser(next){try{localStorage.setItem(presetKey,JSON.stringify(next));userPresets=next;storageAvailable=true;return true;}catch(e){storageAvailable=false;sayPreset('Could not save: browser storage is unavailable or full. Export a backup.',true);return false;}}
function refreshMachine(){const query=mSearch.value.trim().toLocaleLowerCase(), current=selectedMachine;mSelect.replaceChildren();const place=document.createElement('option');place.value='';place.textContent='Choose from 250 machine presets';mSelect.appendChild(place);let count=0;machinePresets.forEach(p=>{if(!(`${p.id} ${p.name}`.toLocaleLowerCase().includes(query)))return;const opt=document.createElement('option');opt.value=p.id;opt.textContent=p.id+' · '+p.name;mSelect.appendChild(opt);count++;});mSelect.value=current;if(!mSelect.value)mSelect.value='';document.getElementById('machine-count').textContent=`${count} / 250`;}
function chooseMachine(id){const p=machinePresets.find(x=>x.id===id);if(!p)return;applySnapshot(p.settings);selectedMachine=p.id;mSelect.value=p.id;uSelect.value='';uName.value=p.name;sayPreset(`${p.id} · ${p.name} loaded. Machine snapshots never change.`);}
mSearch.addEventListener('input',refreshMachine);mSelect.addEventListener('change',()=>chooseMachine(mSelect.value));
for(const [id,direction] of [['machine-prev',-1],['machine-next',1]])document.getElementById(id).addEventListener('click',()=>{const ids=Array.from(mSelect.options).map(o=>o.value).filter(Boolean);if(!ids.length){sayPreset('No machine presets match that search.',true);return;}const i=ids.indexOf(mSelect.value);chooseMachine(ids[i<0?(direction>0?0:ids.length-1):(i+direction+ids.length)%ids.length]);});
uSelect.addEventListener('change',()=>{if(uSelect.value==='')return;const p=userPresets[Number(uSelect.value)];if(!p)return;applySnapshot(p.settings);uName.value=p.name;selectedMachine='';mSelect.value='';sayPreset(`Loaded “${p.name}”.`);});
document.getElementById('user-save').addEventListener('click',()=>{const name=uName.value.trim();if(!name){sayPreset('Enter a name before saving.',true);uName.focus();return;}const index=userPresets.findIndex(p=>p.name.toLocaleLowerCase()===name.toLocaleLowerCase());if(index>=0&&!confirm(`Replace your saved preset “${userPresets[index].name}”?`))return;const next=clone(userPresets);const p={name,settings:snapshot()};if(index>=0)next[index]=p;else next.push(p);if(storeUser(next)){const selected=String(index>=0?index:next.length-1);refreshUser(selected);sayPreset(`Saved “${name}” in this browser.`);}});
document.getElementById('user-delete').addEventListener('click',()=>{if(uSelect.value===''){sayPreset('Select a saved preset to delete.',true);return;}const i=Number(uSelect.value);if(!userPresets[i]||!confirm(`Delete “${userPresets[i].name}”?`))return;const next=clone(userPresets);const name=next[i].name;next.splice(i,1);if(storeUser(next)){refreshUser();sayPreset(`Deleted “${name}”. Machine presets are untouched.`);}});
document.getElementById('user-export').addEventListener('click',()=>{const data=JSON.stringify({format:'signal-lab-presets',version:1,presets:userPresets},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='signal-lab-presets.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);sayPreset(`Exported ${userPresets.length} personal preset(s).`);});
document.getElementById('user-import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('File is too large (2 MB maximum).');const data=JSON.parse(await file.text());const list=Array.isArray(data)?data:data.presets;if(!Array.isArray(list)||!list.every(validPreset))throw Error('This is not a valid preset backup.');if(!confirm(`Import ${list.length} preset(s)? Matching personal preset names will be replaced.`))return;const next=clone(userPresets);list.forEach(p=>{const ix=next.findIndex(q=>q.name.toLocaleLowerCase()===p.name.toLocaleLowerCase());if(ix>=0)next[ix]=clone(p);else next.push(clone(p));});if(storeUser(next)){refreshUser();sayPreset(`Imported ${list.length} preset(s).`);}}catch(err){sayPreset(`Import failed: ${err.message}`,true);}finally{e.target.value='';}});
readUser();refreshMachine();

